def trimmed_lzma(value: Any) -> tuple[str, int]:
    decoded = orjson.dumps(value)
    compressed = bytearray(
        lzma.compress(
            decoded,
            format=lzma.FORMAT_ALONE,
            filters=[
                {
                    "id": lzma.FILTER_LZMA1,
                    "dict_size": 1 << 18,
                    "lc": 3,
                    "lp": 0,
                    "pb": 2,
                }
            ],
        )
    )
    compressed[5:13] = len(decoded).to_bytes(8, "little")
    trimmed = compressed[:9] + compressed[13:]
    return base64.b64encode(trimmed).decode(), len(decoded)


def chunked_messages(
    document: Any,
    *,
    batid: str,
    mid: str = "0",
    chunks: int = 1,
) -> list[dict[str, Any]]:
    info, info_size = trimmed_lzma(document)
    raw = base64.b64decode(info, validate=True)
    chunk_size = max(1, (len(raw) + chunks - 1) // chunks)
    parts = [
        raw[index : index + chunk_size] for index in range(0, len(raw), chunk_size)
    ]
    return [
        {
            "body": {
                "data": {
                    "mid": mid,
                    "batid": batid,
                    "serial": str(len(parts)),
                    "index": str(index),
                    "infoSize": info_size,
                    "info": base64.b64encode(part).decode(),
                }
            }
        }
        for index, part in enumerate(parts)
    ]
